  "encoding": {
    "x": {
      "field": "age",
      "type": "ordinal",
      "title": "Age Group",
      "axis": {"labelAngle": 0}
    },
    "y": {
      "field": "share",
      "type": "quantitative",
      "title": "Share of Population (%)"
    }
  },
  "layer": [
    {
      "mark": "point",
      "encoding": {
        "color": {"value": "steelblue"}
      }
    },
    {
      "mark": "text",
      "encoding": {
        "text": {"field": "share", "type": "quantitative"},
        "x": {"field": "age", "type": "ordinal"},
        "y": {"field": "share", "type": "quantitative"},
        "color": {"value": "black"}
