code:
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "values": [
      {"Country": "Country A", "Residential": 120, "Industrial": 180, "Transportation": 100},
      {"Country": "Country B", "Residential": 200, "Industrial": 150, "Transportation": 150},
      {"Country": "Country C", "Residential": 80, "Industrial": 220, "Transportation": 100},
      {"Country": "Country D", "Residential": 150, "Industrial": 130, "Transportation": 70},
      {"Country": "Country E", "Residential": 90, "Industrial": 190, "Transportation": 120},
      {"Country": "Country F", "Residential": 110, "Industrial": 160, "Transportation": 130}
    ]
  },
  "transform": [
    {
      "calculate": "(datum.Industrial / (datum.Residential + datum.Industrial + datum.Transportation)) * 100",
      "as": "IndustrialPercentage"
    }
  ],
  "mark": "bar",
  "encoding": {
    "x": {
      "field": "Country",
      "type": "nominal",
      "axis": {"labelAngle": 0},
      "title": "Country"
    },
    "y": {
      "field": "IndustrialPercentage",
      "type": "quantitative",
      "title": "Industrial Energy Consumption (%)"
    },
    "color": {
      "condition": {
        "test": "datum.Country === 'Country C'",
        "value": "orange"
      },
      "value": "steelblue"
    }
  },
  "title": "Industrial Energy Consumption as a Percentage of Total Energy Consumption"
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "values": [
      {"Category": "Store A", "Monthly_Foot_Traffic": 50, "Average_Transaction_Value": 20, "Conversion_Rate": 10},
      {"Category": "Store B", "Monthly_Foot_Traffic": 70, "Average_Transaction_Value": 25, "Conversion_Rate": 12},
      {"Category": "Store C", "Monthly_Foot_Traffic": 60, "Average_Transaction_Value": 15, "Conversion_Rate": 8},
      {"Category": "Store D", "Monthly_Foot_Traffic": 80, "Average_Transaction_Value": 30, "Conversion_Rate": 15},
      {"Category": "Store E", "Monthly_Foot_Traffic": 90, "Average_Transaction_Value": 35, "Conversion_Rate": 11},
      {"Category": "Store F", "Monthly_Foot_Traffic": 40, "Average_Transaction_Value": 18, "Conversion_Rate": 7}
    ]
  },
  "transform": [
    {
      "calculate": "datum.Monthly_Foot_Traffic * datum.Conversion_Rate * datum.Average_Transaction_Value",
      "as": "Total_Monthly_Revenue"
    }
  ],
  "mark": "bar",
  "encoding": {
    "x": {
      "field": "Category",
      "type": "nominal",
      "axis": {"labelAngle": 0},
      "title": "Store"
    },
    "y": {
      "field": "Total_Monthly_Revenue",
      "type": "quantitative",
      "title": "Total Monthly Revenue"
    },
    "color": {
      "field": "Category",
      "type": "nominal",
      "legend": null
    }
  },
  "title": "Total Monthly Revenue by Store",
  "config": {
    "axis": {
      "labelFontSize": 12,
      "titleFontSize": 14
    },
    "title": {
      "fontSize": 16
    }
  }
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "values": [
      {"Medication": "Med A", "AverageBP": 120, "StdDevBP": 1.58},
      {"Medication": "Med B", "AverageBP": 130, "StdDevBP": 1.58},
      {"Medication": "Med C", "AverageBP": 116, "StdDevBP": 1.58},
      {"Medication": "Med D", "AverageBP": 141, "StdDevBP": 1.58},
