      {"Medication": "Med F", "AverageBP": 111, "StdDevBP": 1.58}
    ]
  },
  "title": "Medication Efficacy: Average and Variability of Blood Pressure",
  "layer": [
    {
      "mark": "bar",
      "encoding": {
        "x": {"field": "Medication", "type": "nominal", "axis": {"labelAngle": 0}},
        "y": {"field": "AverageBP", "type": "quantitative", "title": "Average Blood Pressure"},
        "color": {"value": "#4C78A8"}
      }
    },
    {
      "mark": {
        "type": "errorbar",
        "extent": "stdev",
        "ticks": true
      },
      "encoding": {
        "x": {"field": "Medication", "type": "nominal"},
        "y": {"field": "AverageBP", "type": "quantitative"},
        "yError": {"field": "StdDevBP", "type": "quantitative"}
      }
    },
    {
      "mark": "text",
      "encoding": {
        "x": {"field": "Medication", "type": "nominal"},
        "y": {"field": "AverageBP", "type": "quantitative", "stack": "zero"},
        "text": {"field": "AverageBP", "type": "quantitative"},
        "color": {"value": "black"}
      },
      "transform": [{"calculate": "datum.AverageBP", "as": "AverageBP"}]
    }
  ],
  "config": {
    "axis": {
      "labelFontSize": 12,
      "titleFontSize": 14
    },
    "title": {
      "fontSize": 16
