code:
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "values": [
      {"Department": "Cardiology", "WaitTime": 15},
      {"Department": "Cardiology", "WaitTime": 20},
      {"Department": "Cardiology", "WaitTime": 30},
      {"Department": "Cardiology", "WaitTime": 25},
      {"Department": "Cardiology", "WaitTime": 20},
      {"Department": "Neurology", "WaitTime": 40},
      {"Department": "Neurology", "WaitTime": 45},
      {"Department": "Neurology", "WaitTime": 35},
      {"Department": "Neurology", "WaitTime": 50},
      {"Department": "Neurology", "WaitTime": 55},
      {"Department": "Orthopedics", "WaitTime": 10},
      {"Department": "Orthopedics", "WaitTime": 15},
      {"Department": "Orthopedics", "WaitTime": 20},
      {"Department": "Orthopedics", "WaitTime": 10},
      {"Department": "Orthopedics", "WaitTime": 15},
      {"Department": "Oncology", "WaitTime": 60},
      {"Department": "Oncology", "WaitTime": 65},
      {"Department": "Oncology", "WaitTime": 70},
      {"Department": "Oncology", "WaitTime": 75},
      {"Department": "Oncology", "WaitTime": 80},
      {"Department": "Pediatrics", "WaitTime": 20},
      {"Department": "Pediatrics", "WaitTime": 25},
      {"Department": "Pediatrics", "WaitTime": 15},
      {"Department": "Pediatrics", "WaitTime": 30},
      {"Department": "Pediatrics", "WaitTime": 35},
      {"Department": "Emergency", "WaitTime": 5},
      {"Department": "Emergency", "WaitTime": 10},
      {"Department": "Emergency", "WaitTime": 8},
      {"Department": "Emergency", "WaitTime": 12},
      {"Department": "Emergency", "WaitTime": 7}
    ]
  },
  "transform": [
    {
      "aggregate": [{"op": "mean", "field": "WaitTime", "as": "AverageWaitTime"}],
      "groupby": ["Department"]
    },
    {
      "aggregate": [{"op": "median", "field": "AverageWaitTime", "as": "OverallMedian"}]
    },
    {
      "filter": "datum.AverageWaitTime < datum.OverallMedian"
    },
    {
      "joinaggregate": [
        {"op": "q1", "field": "WaitTime", "as": "Q1"},
        {"op": "q3", "field": "WaitTime", "as": "Q3"}
      ],
      "groupby": ["Department"]
    },
    {
      "calculate": "datum.Q3 - datum.Q1",
      "as": "IQR"
    },
    {
      "window": [{"op": "min", "field": "IQR", "as": "MinIQR"}],
      "groupby": []
    },
    {
      "filter": "datum.IQR === datum.MinIQR"
    }
  ],
  "mark": "bar",
  "encoding": {
    "x": {"field": "Department", "type": "nominal", "title": "Department"},
    "y": {"field": "AverageWaitTime", "type": "quantitative", "title": "Average Wait Time (minutes)"},
    "color": {"value": "#4C78A8"}
  },
  "title": "Department with Lowest Average Wait Time and Smallest IQR",
  "config": {
    "axis": {"labelAngle": 0},
    "view": {"stroke": "transparent"}
  }
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "values": [
      {"Category": "Coal", "Value": 3000},
      {"Category": "Natural Gas", "Value": 2500},
      {"Category": "Nuclear", "Value": 1500},
      {"Category": "Hydroelectric", "Value": 1000},
      {"Category": "Wind", "Value": 800},
      {"Category": "Solar", "Value": 1400},
      {"Category": "Biomass", "Value": 500}
    ]
  },
  "transform": [
    {
      "calculate": "datum.Category == 'Hydroelectric' || datum.Category == 'Wind' || datum.Category == 'Solar' || datum.Category == 'Biomass' ? datum.Value : 0",
      "as": "Renewable"
    },
    {
      "aggregate": [{"op": "sum", "field": "Value", "as": "Total"}]
    },
    {
      "aggregate": [{"op": "sum", "field": "Renewable", "as": "RenewableTotal"}]
    },
    {
      "calculate": "(datum.RenewableTotal / datum.Total) * 100",
      "as": "RenewablePercentage"
    }
  ],
  "mark": "bar",
  "encoding": {
    "x": {"field": "Category", "type": "nominal", "axis": {"labelAngle": -45}},
    "y": {"field": "Value", "type": "quantitative"},
    "color": {
      "field": "Category",
      "type": "nominal",
      "scale": {
        "domain": ["Coal", "Natural Gas", "Nuclear", "Hydroelectric", "Wind", "Solar", "Biomass"],
        "range": ["#a6cee3", "#1f78b4", "#b2df8a", "#33a02c", "#fb9a99", "#e31a1c", "#fdbf6f"]
      }
    }
  },
  "title": "Energy Production by Source with Increased Solar Output",
  "config": {
    "axis": {"labelFontSize": 12, "titleFontSize": 14},
    "title": {"fontSize": 16, "anchor": "start"}
  }
}

