      {"Entity": "Germany", "Year": 2006, "Value": 72.16},
      {"Entity": "Germany", "Year": 2007, "Value": 75.16},
      {"Entity": "Germany", "Year": 2008, "Value": 78.0},
      {"Entity": "Malta", "Year": 2003, "Value": 31.64},
      {"Entity": "Malta", "Year": 2004, "Value": 34.62},
      {"Entity": "Malta", "Year": 2005, "Value": 41.24},
      {"Entity": "Malta", "Year": 2006, "Value": 40.41},
      {"Entity": "Malta", "Year": 2007, "Value": 46.9},
      {"Entity": "Malta", "Year": 2008, "Value": 50.08},
      {"Entity": "Bolivia", "Year": 2003, "Value": 3.51},
