  "encoding": {
    "x": {
      "field": "Entity",
      "type": "nominal",
      "axis": {"title": "Country"}
    },
    "y": {
      "field": "AverageAnnualIncrease",
      "type": "quantitative",
      "axis": {"title": "Average Annual Increase"}
