  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "Bar chart showing the importance levels for Germany and the U.S.",
  "data": {
    "values": [
      {"Entity": "Germany", "Importance": "Not important at all", "Value": 15},
      {"Entity": "Germany", "Importance": "Not too important", "Value": 30},
      {"Entity": "Germany", "Importance": "Somewhat important", "Value": 37},
      {"Entity": "Germany", "Importance": "Very important", "Value": 15},
      {"Entity": "U.S", "Importance": "Not important at all", "Value": 5},
      {"Entity": "U.S", "Importance": "Not too important", "Value": 8},
      {"Entity": "U.S", "Importance": "Somewhat important", "Value": 29},
      {"Entity": "U.S", "Importance": "Very important", "Value": 56}
    ]
  },
  "mark": "bar",
  "encoding": {
    "x": {
      "field": "Importance",
      "type": "nominal",
      "axis": {"title": "Importance Level", "labelAngle": 0}
    },
    "y": {
      "field": "Value",
      "type": "quantitative",
      "axis": {"title": "Percentage"}
    },
    "color": {
      "field": "Entity",
      "type": "nominal",
      "scale": {"range": ["#1f77b4", "#ff7f0e"]},
      "legend": {"title": "Country"}
    }
  },
  "config": {
    "axis": {
      "labelFontSize": 12,
      "titleFontSize": 14
    },
    "legend": {
      "labelFontSize": 12,
      "titleFontSize": 14
    }
  },
  "title": "Importance Levels: Germany vs U.S.",
  "transform": [
    {
      "calculate": "abs(datum['Value'] - (datum['Entity'] === 'Germany' ? 5 : 15))",
      "as": "Difference"
    }
  ],
  "encoding": {
    "opacity": {
      "condition": {"test": "datum.Difference === 7", "value": 1},
      "value": 0.3
    }
  }
}

