{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": "Average Number of Casualties per Incident in Southeast Asia, 2010",
  "data": {
    "values": [
      {"Category": "Non-fatal Injuries", "Count": 634},
      {"Category": "Fatalities", "Count": 322}
    ]
  },
