  "data": {
    "values": [
      {"TimePeriod": "Day 1", "Open": 100, "High": 105, "Low": 95, "Close": 104},
      {"TimePeriod": "Day 2", "Open": 104, "High": 110, "Low": 101, "Close": 108},
      {"TimePeriod": "Day 3", "Open": 108, "High": 115, "Low": 107, "Close": 112},
      {"TimePeriod": "Day 4", "Open": 112, "High": 113, "Low": 109, "Close": 110},
      {"TimePeriod": "Day 5", "Open": 110, "High": 111, "Low": 105, "Close": 106},
      {"TimePeriod": "Day 6", "Open": 106, "High": 108, "Low": 102, "Close": 103},
      {"TimePeriod": "Day 7", "Open": 103, "High": 104, "Low": 98, "Close": 99}
    ]
  },
  "layer": [
    {
      "mark": "line",
      "encoding": {
        "x": {"field": "TimePeriod", "type": "ordinal", "title": "Time Period"},
        "y": {"field": "Close", "type": "quantitative", "title": "Price"},
        "color": {"value": "steelblue"}
      }
    },
    {
      "transform": [
        {
          "window": [{"op": "mean", "field": "Close", "as": "3-day MA"}],
          "frame": [-2, 0]
