      ],
      "mark": "line",
      "encoding": {
        "x": {"field": "TimePeriod", "type": "ordinal"},
        "y": {"field": "3-day MA", "type": "quantitative"},
        "color": {"value": "orange"}
      }
    },
    {
      "mark": "rule",
      "encoding": {
        "x": {"field": "TimePeriod", "type": "ordinal"},
        "y": {"field": "Low", "type": "quantitative"},
        "y2": {"field": "High"},
        "color": {"value": "gray"}
      }
    },
