{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "values": [
      {"Player": "Player A", "Game1_Score": 20, "Game2_Score": 22, "Game3_Score": 19},
      {"Player": "Player B", "Game1_Score": 15, "Game2_Score": 17, "Game3_Score": 14},
      {"Player": "Player C", "Game1_Score": 25, "Game2_Score": 28, "Game3_Score": 26},
      {"Player": "Player D", "Game1_Score": 18, "Game2_Score": 20, "Game3_Score": 21},
      {"Player": "Player E", "Game1_Score": 22, "Game2_Score": 24, "Game3_Score": 23},
      {"Player": "Player F", "Game1_Score": 16, "Game2_Score": 18, "Game3_Score": 17}
    ]
  },
  "transform": [
    {
      "calculate": "(datum.Game1_Score + datum.Game2_Score + datum.Game3_Score) / 3",
