      "encoding": {
        "x": {"field": "Player", "type": "nominal", "axis": {"labelAngle": 0}},
        "y": {"field": "Total_Score", "type": "quantitative"},
        "color": {
          "condition": {
            "test": "datum.Player === 'Player D'",
