{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "values": [
      {"Region": "Region A", "Coal": 150, "Oil": 100, "Gas": 80, "Renewable": 200},
      {"Region": "Region B", "Coal": 200, "Oil": 90, "Gas": 120, "Renewable": 90},
      {"Region": "Region C", "Coal": 180, "Oil": 110, "Gas": 60, "Renewable": 80},
      {"Region": "Region D", "Coal": 170, "Oil": 95, "Gas": 85, "Renewable": 180},
      {"Region": "Region E", "Coal": 160, "Oil": 85, "Gas": 90, "Renewable": 220},
      {"Region": "Region F", "Coal": 190, "Oil": 105, "Gas": 70, "Renewable": 60}
    ]
  },
  "transform": [
    {"fold": ["Coal", "Oil", "Gas", "Renewable"], "as": ["Energy", "Value"]},
    {
      "window": [{"op": "sum", "field": "Value", "as": "Total"}],
      "groupby": ["Region"]
    },
    {
      "calculate": "datum.Value / datum.Total * 100",
      "as": "Percentage"
    },
    {
      "window": [{"op": "rank", "field": "Percentage", "as": "Rank"}],
      "groupby": ["Region"],
      "sort": [{"field": "Percentage", "order": "ascending"}]
    },
    {"filter": "datum.Rank <= 2"},
    {
      "aggregate": [{"op": "sum", "field": "Percentage", "as": "CumulativePercentage"}],
      "groupby": ["Region"]
    }
  ],
  "mark": "bar",
  "encoding": {
    "x": {"field": "Region", "type": "nominal", "title": "Region"},
    "y": {"field": "CumulativePercentage", "type": "quantitative", "title": "Cumulative Percentage of Two Least Contributing Sources"},
    "color": {"field": "Region", "type": "nominal", "legend": null}
  },
  "title": "Cumulative Percentage of Two Least Contributing Energy Sources by Region"
}

