{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "Donut chart showing the proportion of top 10 names.",
  "data": {
    "values": [
      {"name": "Emma", "registrations": 608},
      {"name": "Olivia", "registrations": 554},
      {"name": "Louise", "registrations": 545},
      {"name": "Mila", "registrations": 536},
      {"name": "Alice", "registrations": 422},
      {"name": "Juliette", "registrations": 373},
      {"name": "Elena", "registrations": 369},
      {"name": "Marie", "registrations": 369},
      {"name": "Sofia", "registrations": 368},
      {"name": "Lina", "registrations": 362}
    ]
  },
  "transform": [
    {
      "window": [{"op": "sum", "field": "registrations", "as": "Total"}],
      "frame": [null, null]
    },
    {
      "calculate": "datum.registrations / datum.Total * 100",
      "as": "percentage"
    }
  ],
  "mark": {"type": "arc", "innerRadius": 50},
  "encoding": {
    "theta": {"field": "registrations", "type": "quantitative"},
    "color": {"field": "name", "type": "nominal", "legend": null},
    "tooltip": [
      {"field": "name", "type": "nominal"},
      {"field": "registrations", "type": "quantitative"},
      {"field": "percentage", "type": "quantitative", "format": ".1f"}
    ]
  },
  "view": {"stroke": null},
  "title": "Proportion of Top 10 Names in Registrations"
}
